arguments.command:
sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'EOF'
# ADR-0009: 4 attempts, waits 3/9/27 s; RELAY_ATTEMPTS sets the count (runbook), RELAY_RETRY_MAX is ignored.
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "RELAY_ATTEMPTS"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RETRY_MAX ignored"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts"; fail=1; }
exit $fail
EOF
sed -i 's/^3 attempts with doubling waits.*/Superseded by ADR-0009: 4 attempts, waits 3, 9, 27 s (39 s budget). The count can be raised with RELAY_ATTEMPTS for a slow partner./; s/is 7 s enough?/answered by ADR-0009 (7 s was not enough; budget is now 39 s)./' docs/design/delivery.md
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- fix: deliver follows ADR-0009 (4 attempts, waits 3\/9\/27 s) and reads the count from `RELAY_ATTEMPTS` as the runbook says (RLY-731)\n\n## 3.4.1/' CHANGELOG.md
git diff --stat; bash tests/deliver_test.sh; echo rc=$?; bash scripts/verify.sh

